module CardArrangementOptimizer(\n    input wire clk,\n    input wire rst_n,\n    input wire start,\n    input wire [2:0] a,\n    input wire [2:0] b,\n    output reg done,\n    output reg signed [7:0] score,\n    output reg [7:0] arrangement,\n    output reg [3:0] length\n);\n\n    // State declarations\n    localparam [2:0] IDLE       = 3'd0;\n    localparam [2:0] LOAD       = 3'd1;\n    localparam [2:0] COMPUTE_P  = 3'd2;\n    localparam [2:0] BUILD_ARR  = 3'd3;\n    localparam [2:0] FINISH     = 3'd4;\n\n    reg [2:0] state, next_state;\n\n    // Data registers\n    reg [2:0] a_reg;\n    reg [2:0] b_reg;\n    reg [2:0] p_counter;\n\n    // Best candidate tracking\n    reg signed [7:0] best_score;\n    reg [2:0] best_p;\n    reg [2:0] best_q;\n    reg [2:0] best_r;\n\n    // Computation variables\n    wire [3:0] gaps;\n    wire [2:0] q;\n    wire [2:0] r;\n    wire [4:0] sum_o_sq;\n    wire [7:0] sum_x_sq;\n    wire [7:0] q_sq;\n    wire [7:0] qp1_sq;\n    wire signed [8:0] score_candidate;\n\n    assign gaps = p_counter + 3'd1;\n\n    // div_rem: Section to compute q and r\n    assign q = b_reg / gaps;\n    assign r = b_reg % gaps;\n\n    // sum_o_sq = (a_reg - p + 1)^2 + (p - 1)\n    assign sum_o_sq = ((a_reg - p_counter + 3'd1) * (a_reg - p_counter + 3'd1)) + (p_counter - 3'd1);\n\n    // sum_x_sq = r*(q+1)^2 + (gaps - r)*q^2\n    assign q_sq = q * q;\n    assign qp1_sq = (q + 3'd1) * (q + 3'd1);\n    assign sum_x_sq = r * qp1_sq + (gaps - r) * q_sq;\n\n    // score_candidate = sum_o_sq - sum_x_sq\n    assign score_candidate = $signed({1'b0, sum_o_sq}) - $signed({1'b0, sum_x_sq});\n\n    integer i;  // Loop variable declaration\n\n    // FSM and computation\n    always @(posedge clk or negedge rst_n) begin\n        if (!rst_n) begin\n            state <= IDLE;\n            done <= 1'b0;\n            score <= 8'd0;\n            arrangement <= 8'd0;\n            length <= 4'd0;\n            a_reg <= 3'd0;\n            b_reg <= 3'd0;\n            p_counter <= 3'd0;\n            best_score <= -8'sd128;\n            best_p <= 3'd0;\n            best_q <= 3'd0;\n            best_r <= 3'd0;\n        end else begin\n            case (state)\n                IDLE: begin\n                    done <= 1'b0;\n                    if (start) begin\n                        a_reg <= a;\n                        b_reg <= b;\n                        state <= LOAD;\n                    end else begin\n                        state <= IDLE;\n                    end\n                end\n                LOAD: begin\n                    if (a_reg == 3'd0) begin\n                        score <= - (b_reg * b_reg);\n                        state <= BUILD_ARR;\n                    end else if (b_reg == 3'd0) begin\n                        score <= a_reg * a_reg;\n                        state <= BUILD_ARR;\n                    end else begin\n                        p_counter <= 3'd1;\n                        best_score <= -8'sd128;\n                        state <= COMPUTE_P;\n                    end\n                end\n                COMPUTE_P: begin\n                    if (score_candidate > best_score) begin\n                        best_score <= score_candidate;\n                        best_p <= p_counter;\n                        best_q <= q;\n                        best_r <= r;\n                    end\n                    if (p_counter == a_reg) begin\n                        state <= BUILD_ARR;\n                    end else begin\n                        p_counter <= p_counter + 3'd1;\n                    end\n                end\n                BUILD_ARR: begin\n                    score <= best_score;\n                    arrangement <= 8'b0;\n                    if (a_reg == 3'd0) begin\n                        // All 'x'\n                        length <= b_reg;\n                        for (i = 0; i < b_reg; i = i + 1) begin\n                            arrangement[i] <= 1'b0;\n                        end\n                    end else if (b_reg == 3'd0) begin\n                        // All 'o'\n                        length <= a_reg;\n                        for (i = 0; i < a_reg; i = i + 1) begin\n                            arrangement[i] <= 1'b1;\n                        end\n                    end else begin\n                        // Build arrangement based on best_p, best_q, best_r\n                        length <= a_reg + b_reg;\n                        begin : BUILD_ARRANGEMENT\n                            integer j, pos;\n                            reg [2:0] gap_size;\n                            reg [4:0] large_o_val;\n                            pos = 0;\n                            large_o_val = a_reg - best_p + 3'd1;\n\n                            gap_size = (3'd0 < best_r) ? best_q + 3'd1 : best_q;\n                            for (j = 0; j < gap_size; j = j + 1) begin\n                                if (pos < 8) arrangement[pos] <= 1'b0;\n                                pos = pos + 1;\n                            end\n\n                            for (j = 0; j < large_o_val; j = j + 1) begin\n                                if (pos < 8) arrangement[pos] <= 1'b1;\n                                pos = pos + 1;\n                            end\n\n                            for (i = 3'd1; i < best_p; i = i + 3'd1) begin\n                                gap_size = (i < best_r) ? best_q + 3'd1 : best_q;\n                                for (j = 0; j < gap_size; j = j + 1) begin\n                                    if (pos < 8) arrangement[pos] <= 1'b0;\n                                    pos = pos + 1;\n                                end\n                                if (pos < 8) arrangement[pos] <= 1'b1;\n                                pos = pos + 1;\n                            end\n\n                            gap_size = (best_p < best_r) ? best_q + 3'd1 : best_q;\n                            for (j = 0; j < gap_size; j = j + 1) begin\n                                if (pos < 8) arrangement[pos] <= 1'b0;\n                                pos = pos + 1;\n                            end\n                        end\n                    end\n                    state <= FINISH;\n                end\n                FINISH: begin\n                    done <= 1'b1;\n                    state <= IDLE;\n                end\n                default: state <= IDLE;\n            endcase\n        end\n    end\n\nendmodule